window.AUTH=window.AUTH||{};window.AUTH["13-1371"]={"d":"13-1371","id":"2014/13-1371","n":"Texas Dept. of Housing and Community Affairs v. Inclusive Communities Project, Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondent","date":"2014-12-23","url":"https://www.justice.gov/osg/media/399986/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/texas-dept-hous-and-cmty-affairs-v-inclusive-cmtys-project","n":75}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep576/usrep576519/usrep576519.pdf","tr":true,"items":[{"t":"case","label":"Arthur v. City of Toledo","cite":"782 F.2d 565","y":1986,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/782/565/","op":1,"by":{"0":"3"}},{"t":"case","label":"Bilski v. Kappos","cite":"561 U.S. 593","y":2010,"id":"2009/08-964","sc":1,"sum":"The Court held that the \"machine-or-transformation\" test adopted by the Patent and Trademark Office (PTO) was a legal means for determining patent eligibility.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Board of Educ. v. Harris","cite":"444 U.S. 130","y":1979,"id":"1979/78-873","sc":1,"op":3,"sum":"Holding the term “discriminat[e]” encompassed disparate-impact liability in the context of a statute's text, history, purpose, and structure.","sumSrc":"opinion","by":{"0":"21, 22"}},{"t":"case","label":"CSX Transp., Inc. v. Alabama Dep’t of Revenue","cite":"131 S. Ct. 1101","y":2011,"id":"2010/09-520","sc":1,"op":1,"sum":"The Court held that a railroad company could invoke the Railroad Revitalization and Regulatory Reform Act to challenge sales and use taxes that apply to rail carriers, but exempt their competitors in the transportation industry.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":1,"ar":5,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"9, 15"}},{"t":"case","label":"City of Edmonds v. Oxford House, Inc.","cite":"514 U.S. 725","y":1995,"id":"1994/94-23","sc":1,"ar":1,"sum":"The Court held that Edmonds' zoning code definition of the term \"family\" is not a maximum occupancy restriction exempt from the FHA.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"City of Mobile v. Bolden","cite":"446 U.S. 55","y":1980,"id":"1978/77-1844","sc":1,"sum":"The Court held that the Fifteenth Amendment did not entail \"the right to have Negro candidates elected,\" and that only purposefully discriminatory denials of the freedom to vote on the basis of race demanded constitutional remedies.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Forest Grove Sch. Dist. v. T.A.","cite":"557 U.S. 230","y":2009,"id":"2008/08-305","sc":1,"op":6,"sum":"The Court found that the Individuals with Disabilities Education Act (IDEA) can authorize a public school to reimburse a student for private school tuition sought because the student never received special education services at the public school.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"General Dynamics Land Sys. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Guardians v. Civil Service Com’n","cite":"463 U.S. 582","y":1983,"id":"1982/81-431","sc":1,"op":1,"sum":"Holding that Title VI, 42 U. S. C. § 2000d et seq., does “not allow compensatory relief in the absence of proof of discriminatory intent”.","sumSrc":"opinion","by":{"0":"21"}},{"t":"case","label":"Greater New Orleans Fair Hous. Action Ctr. v. HUD","cite":"639 F.3d 1078","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/639/1078/","op":1,"sum":"Holding HUD exceeded its authority in promulgating the disparate-impact rule.","sumSrc":"brief:0","by":{"0":"5"}},{"t":"case","label":"Griggs v. Duke Power Co.","cite":"401 U.S. 424","y":1971,"id":"1970/124","sc":1,"op":55,"ar":4,"sum":"After noting that Title VII of the Act intended to achieve equality of employment opportunities, the Court held that Duke's standardized testing requirement prevented a disproportionate number of African-American employees from being hired by, and advancing to higher-paying departments within, the company.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"HUD v. Carter","cite":"1992 WL 406520","y":1992,"court":"HUD ALJ May 1","by":{"0":"15"}},{"t":"case","label":"HUD v. Mountain Side Mobile Estates P’ship","cite":"1993 WL 307069","y":1993,"court":"July 19","by":{"0":"15"}},{"t":"case","label":"HUD v. Pfaff","cite":"1994 WL 592199","y":1994,"court":"HUD ALJ Oct. 27","by":{"0":"15"}},{"t":"case","label":"HUD v. Twinbrook Vill. Apartments","cite":"2001 WL 1632533","y":2001,"court":"HUD ALJ Nov. 9","by":{"0":"15"}},{"t":"case","label":"Halet v. Wend Inv. Co.","cite":"672 F.2d 1305","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/672/1305/","op":1,"by":{"0":"3"}},{"t":"case","label":"Hanson v. Veterans Admin.","cite":"800 F.2d 1381","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/800/1381/","op":1,"by":{"0":"3"}},{"t":"case","label":"Havens Realty Corp. v. Coleman","cite":"455 U.S. 363","y":1982,"id":"1981/80-988","sc":1,"sum":"Section 804 of the Fair Housing Act of 1968 (Act) makes unlawful various forms of discriminatory housing practices. Section 812(a) authorizes civil actions to enforce §804 and requires that suit be brought within 180 days after the alleged occurrence of a discriminatory practice. A class action for declaratory, injunctive, and monetary relief was brought in Federal District Court against petitioners-Havens Realty …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Huntington Branch, NAACP v. Town of Huntington","cite":"844 F.2d 926","y":1988,"url":"https://www.courtlistener.com/c/F.2d/844/926/","op":1,"by":{"0":"3"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Langlois v. Abington Hous. Auth.","cite":"207 F.3d 43","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/207/43/","by":{"0":"5"}},{"t":"case","label":"Lewis v. City of Chicago","cite":"560 U.S. 205","y":2010,"id":"2009/08-974","sc":1,"sum":"The Court held that an employee may file a Title VII disparate impact claim within 300 days after their employer executes the allegedly unlawful practice.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Loving v. United States","cite":"517 U.S. 748","y":1996,"id":"1995/94-1966","sc":1,"sum":"The Court held that not only does the Constitution require the aggravating factors of the military's death penalty, but that the President's prescription of the challenged aggravating factors did not violate the separation-of-powers principle.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Lorillard v. Ponds","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Noting that “every court to consider the issue” had agreed on the statute’s interpretation, and explaining that “Congress is presumed to be aware of an administrative or judicial interpretation of a statute and to adopt that interpretation when it re-enacts a statute without change”.","sumSrc":"brief:0","by":{"0":"24"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"133 S. Ct. 1166","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Meacham v. Knolls Atomic Power Lab.","cite":"554 U.S. 84","y":2008,"id":"2007/06-1505","sc":1,"sum":"Writing for a 7-1 majority on the issue of burden of proof, Justice David Souter stated that the text and structure of the ADEA indicated that it is the employer, not the employee, who must bear both the burden of production and the burden of persuasion for the use of \"reasonable factors other than age\" in the decision to terminate employment.","sumSrc":"Oyez","by":{"0":"17, 24, 31"}},{"t":"case","label":"Metropolitan Hous. Dev. Corp. v. Village of Arlington Heights","cite":"558 F.2d 1283","y":1977,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/558/1283/","op":2,"by":{"0":"3"}},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"ar":1,"sum":"The Court held that the FHA imposes liability without fault upon the employer in accordance with traditional agency principles. In other words, the FHA normally imposes vicarious liability upon the corporation, but not upon its officers or owners.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Mt. Holly Gardens Citizens in Action, Inc. v. Township of Mt. Holly","cite":"658 F.3d 375","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/658/375/","op":5,"ar":1,"by":{"0":"16"}},{"t":"case","label":"Mountain Side Mobile Estates P’ship v. HUD","cite":"56 F.3d 1243","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/56/1243/","by":{"0":"5"}},{"t":"case","label":"New York City Transit Auth. v. Beazer","cite":"440 U.S. 568","y":1979,"id":"1978/77-1427","sc":1,"op":7,"sum":"The Court reversed the Second Circuit and held that the Transit Authority's policy was not unconstitutional or illegal under the Civil Rights Act. Writing for the majority, Justice Stevens described Beazer's statistical argument as \"weak\", as the 81 percent statistic did not relate to methadone users specifically.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Parents Involved in Cmty. Schs. v. Seattle Sch. Dist. No. 1","cite":"551 U.S. 701","y":2007,"id":"2006/05-915","sc":1,"op":3,"ar":1,"sum":"By a 5-4 vote, the Court applied a \"strict scrutiny\" framework and found Jefferson County's enrollment plan unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"35, 36"}},{"t":"case","label":"Regents of Univ. of Cal. v. Bakke","cite":"438 U.S. 265","y":1978,"id":"1979/76-811","sc":1,"sum":"The Court found that any racial quota for the purpose of admissions supported by a government entity violates the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Resident Advisory Bd. v. Rizzo","cite":"564 F.2d 126","y":1977,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/564/126/","op":1,"by":{"0":"3"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"op":11,"ar":3,"sum":"The Court held that a municipality violated Title VII of the Civil Rights Act of 1964 when it rejected otherwise valid civil service exams because the results unintentionally prevented the promotion of minority candidates.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"op":17,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Smith v. Town of Clarkton","cite":"682 F.2d 1055","y":1982,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/682/1055/","op":1,"by":{"0":"3"}},{"t":"case","label":"Smiley v. Citibank","cite":"517 U.S. 735","y":1996,"id":"1995/95-860","sc":1,"sum":"The Court held that the National Bank Act of 1864 authorizes such charges because a regulation adopted by the Comptroller of the Currency, which defined interest to include late-payment fees, was a reasonable interpretation of the act and entitled to deference.","sumSrc":"Oyez","by":{"0":"17, 32"}},{"t":"case","label":"Tennessee v. Lane","cite":"541 U.S. 509","y":2004,"id":"2003/02-1667","sc":1,"op":1,"sum":"In a 5-to-4 opinion written by Justice John Paul Stevens, the Court held that Congress had sufficiently demonstrated the problems faced by disabled persons who sought to exercise fundamental rights protected by the Due Process clause of the 14th Amendment (such as access to a court).","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Town of Huntington v. Huntington Branch, NAACP","cite":"488 U.S. 15","y":1988,"id":"1988/87-1961","sc":1,"op":3,"sum":"Invalidating zoning law preventing con- 540 TEXAS DEPT. OF HOUSING AND COMMUNITY AFFAIRS v. INCLUSIVE COMMUNITIES PROJECT, INC. struction of multifamily rental units.","sumSrc":"opinion","by":{"0":"16"}},{"t":"case","label":"United States v. City of Black Jack","cite":"508 F.2d 1179","y":1974,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/508/1179/","op":5,"sum":"Invalidating ordinance prohibiting construction of new multifamily dwellings.","sumSrc":"opinion","by":{"0":"3"}},{"t":"case","label":"United States v. Giles","cite":"300 U.S. 41","y":1937,"id":"scdb/1936-072","sc":1,"op":1,"sum":"1. The rule that criminal statutes must be strictly construed does not require that the words be given their narrowest meaning or that the evident intent be disregarded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"United States v. Marengo Cnty. Comm’n","cite":"731 F.2d 1546","y":1984,"url":"https://www.courtlistener.com/c/F.2d/731/1546/","op":1,"by":{"0":"3"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Watson v. Fort Worth Bank & Trust","cite":"487 U.S. 977","y":1988,"id":"1987/86-6139","sc":1,"op":1,"sum":"The judgment is vacated, and the case is remanded. 798 F. 2d 791, vacated and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts 1, II-A, II-B, and III, concluding that disparate impact analysis may be applied to a subjective or discretionary promotion system. Pp. 985-991, 999-1000.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 35"}},{"t":"case","label":"West Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"op":5,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"const","label":"Amendment XIV","clauses":[["equal-protection","Equal Protection Clause"]],"by":{"0":"11, 34, 35"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"0":"10, 18, 19, 20, 31"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)(2)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"0":"10, 18, 19, 20, 31, 26"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":28,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"10, 18, 19, 20, 31"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(k)","(k)(3)"],"by":{"0":"27, 27"}},{"t":"law","label":"Pub. L. No. 90-284","url":"https://www.govinfo.gov/link/statute/82/83","by":{"0":"3, 25"}},{"t":"law","label":"Emergency School Aid Act, Pub. L. No. 92-318","url":"https://www.govinfo.gov/link/statute/86/356","by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/42/3601","stext":{"head":"§3601. Declaration of policy","paras":[[0,"It is the policy of the United States to provide, within constitutional limitations, for fair housing throughout the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3601?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§3601. Declaration of policy","tname":"The Public Health and Welfare","by":{"0":"2, 12, 2, 12"}},{"t":"usc","label":"42 U.S.C. § 3604","url":"https://www.law.cornell.edu/uscode/text/42/3604","subs":["(a)"],"stext":{"head":"§3604. Discrimination in the sale or rental of housing and other prohibited practices","paras":[[0,"As made applicable by section 3603 of this title and except as exempted by sections 3603(b) and 3607 of this title, it shall be unlawful—"],[0,"(a) To refuse to sell or rent after the making of a bona fide offer, or to refuse to negotiate for the sale or rental of, or otherwise make unavailable or deny, a dwelling to any person because of race, color, religion, sex, familial status, or national origin."],[0,"(b) To discriminate against any person in the terms, conditions, or privileges of sale or rental of a dwelling, or in the provision of services or facilities in connection therewith, because of race, color, religion, sex, familial status, or national origin."],[0,"(c) To make, print, or publish, or cause to be made, printed, or published any notice, statement, or advertisement, with respect to the sale or rental of a dwelling that indicates any preference, limitation, or discrimination based on race, color, religion, sex, handicap, familial status, or national origin, or an intention to make any such preference, limitation, or discrimination."],[0,"(d) To represent to any person because of race, color, religion, sex, handicap, familial status, or national origin that any dwelling is not available for inspection, sale, or rental when such dwelling is in fact so available."],[0,"(e) For profit, to induce or attempt to induce any person to sell or rent any dwelling by representations regarding the entry or prospective entry into the neighborhood of a person or persons of a particular race, color, religion, sex, handicap, familial status, or national origin."],[0,"(f)(1) To discriminate in the sale or rental, or to otherwise make unavailable or deny, a dwelling to any buyer or renter because of a handicap of—"],[1,"(A) that buyer or renter,1"],[1,"(B) a person residing in or intending to reside in that dwelling after it is so sold, rented, or made available; or"],[1,"(C) any person associated with that buyer or renter."],[0,"(2) To discriminate against any person in the terms, conditions, or privileges of sale or rental of a dwelling, or in the provision of services or facilities in connection with such dwelling, because of a handicap of—"],[1,"(A) that person; or"],[1,"(B) a person residing in or intending to reside in that dwelling after it is so sold, rented, or made available; or"],[1,"(C) any person associated with that person."],[0,"(3) For purposes of this subsection, discrimination includes—"],[1,"(A) a refusal to permit, at the expense of the handicapped person, reasonable modifications of existing premises occupied or to be occupied by such person if such modifications may be necessary to afford such person full enjoyment of the premises except that, in the case of a rental, the landlord may where it is reasonable to do so condition permission for a modification on the renter agreeing to restore the interior of the premises to the condition that existed before the modification, reasonable wear and tear excepted.2"],[1,"(B) a refusal to make reasonable accommodations in rules, policies, practices, or services, when such accommodations may be necessary to afford such person equal opportunity to use and enjoy a dwelling; or"],[1,"(C) in connection with the design and construction of covered multifamily dwellings for first occupancy after the date that is 30 months after September 13, 1988, a failure to design and construct those dwellings in such a manner that—"],[2,"(i) the public use and common use portions of such dwellings are readily accessible to and usable by handicapped persons;"],[2,"(ii) all the doors designed to allow passage into and within all premises within such dwellings are sufficiently wide to allow passage by handicapped persons in wheelchairs; and"],[2,"(iii) all premises within such dwellings contain the following features of adaptive design:"],[3,"(I) an accessible route into and through the dwelling;"],[3,"(II) light switches, electrical outlets, thermostats, and other environmental controls in accessible locations;"],[3,"(III) reinforcements in bathroom walls to allow later installation of grab bars; and"],[3,"(IV) usable kitchens and bathrooms such that an individual in a wheelchair can maneuver about the space."],[0,"(4) Compliance with the appropriate requirements of the American National Standard for buildings and facilities providing accessibility and usability for physically handicapped people (commonly cited as \"ANSI A117.1\") suffices to satisfy the requirements of paragraph (3)(C)(iii)."],[0,"(5)(A) If a State or unit of general local government has incorporated into its laws the requirements set forth in paragraph (3)(C), compliance with such laws shall be deemed to satisfy the requirements of that paragraph."],[0,"(B) A State or unit of general local government may review and approve newly constructed covered multifamily dwellings for the purpose of making determinations as to whether the design and construction requirements of paragraph (3)(C) are met."],[0,"(C) The Secretary shall encourage, but may not require, States and units of local government to include in their existing procedures for the review and approval of newly constructed covered multifamily dwellings, determinations as to whether the design and construction of such dwellings are consistent with paragraph (3)(C), and shall provide technical assistance to States and units of local government and other persons to implement the requirements of paragraph (3)(C)."],[0,"(D) Nothing in this subchapter shall be construed to require the Secretary to review or approve the plans, designs or construction of all covered multifamily dwellings, to determine whether the design and construction of such dwellings are consistent with the requirements of paragraph 3(C)."],[0,"(6)(A) Nothing in paragraph (5) shall be construed to affect the authority and responsibility of the Secretary or a State or local public agency certified pursuant to section 3610(f)(3) of this title to receive and process complaints or otherwise engage in enforcement activities under this subchapter."],[0,"(B) Determinations by a State or a unit of general local government under paragraphs (5)(A) and (B) shall not be conclusive in enforcement proceedings under this subchapter."],[0,"(7) As used in this subsection, the term \"covered multifamily dwellings\" means—"],[1,"(A) buildings consisting of 4 or more units if such buildings have one or more elevators; and"],[1,"(B) ground floor units in other buildings consisting of 4 or more units."],[0,"(8) Nothing in this subchapter shall be construed to invalidate or limit any law of a State or political subdivision of a State, or other jurisdiction in which this subchapter shall be effective, that requires dwellings to be designed and constructed in a manner that affords handicapped persons greater access than is required by this subchapter."],[0,"(9) Nothing in this subsection requires that a dwelling be made available to an individual whose tenancy would constitute a direct threat to the health or safety of other individuals or whose tenancy would result in substantial physical damage to the property of others."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3604?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§3604. Discrimination in the sale or rental of housing and other prohibited practices","tname":"The Public Health and Welfare","by":{"0":"passim"}},{"t":"usc","label":"42 U.S.C. § 3605","url":"https://www.law.cornell.edu/uscode/text/42/3605","subs":["(a)","(c)"],"stext":{"head":"§3605. Discrimination in residential real estate-related transactions","paras":[[0,"(a) In general"],[0,"It shall be unlawful for any person or other entity whose business includes engaging in residential real estate-related transactions to discriminate against any person in making available such a transaction, or in the terms or conditions of such a transaction, because of race, color, religion, sex, handicap, familial status, or national origin."],[0,"(b) \"Residential real estate-related transaction\" defined"],[0,"As used in this section, the term \"residential real estate-related transaction\" means any of the following:"],[1,"(1) The making or purchasing of loans or providing other financial assistance—"],[2,"(A) for purchasing, constructing, improving, repairing, or maintaining a dwelling; or"],[2,"(B) secured by residential real estate."],[1,"(2) The selling, brokering, or appraising of residential real property."],[0,"(c) Appraisal exemption"],[0,"Nothing in this subchapter prohibits a person engaged in the business of furnishing appraisals of real property to take into consideration factors other than race, color, religion, national origin, sex, handicap, or familial status."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3605?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§3605. Discrimination in residential real estate-related transactions","tname":"The Public Health and Welfare","by":{"0":"passim, 5, 24"}},{"t":"usc","label":"42 U.S.C. § 3607","url":"https://www.law.cornell.edu/uscode/text/42/3607","subs":["(b)(1)","(b)(4)"],"stext":{"head":"§3607. Religious organization or private club exemption","paras":[[0,"(a) Nothing in this subchapter shall prohibit a religious organization, association, or society, or any nonprofit institution or organization operated, supervised or controlled by or in conjunction with a religious organization, association, or society, from limiting the sale, rental or occupancy of dwellings which it owns or operates for other than a commercial purpose to persons of the same religion, or from giving preference to such persons, unless membership in such religion is restricted on account of race, color, or national origin. Nor shall anything in this subchapter prohibit a private club not in fact open to the public, which as an incident to its primary purpose or purposes provides lodgings which it owns or operates for other than a commercial purpose, from limiting the rental or occupancy of such lodgings to its members or from giving preference to its members."],[0,"(b)(1) Nothing in this subchapter limits the applicability of any reasonable local, State, or Federal restrictions regarding the maximum number of occupants permitted to occupy a dwelling. Nor does any provision in this subchapter regarding familial status apply with respect to housing for older persons."],[0,"(2) As used in this section, \"housing for older persons\" means housing—"],[1,"(A) provided under any State or Federal program that the Secretary determines is specifically designed and operated to assist elderly persons (as defined in the State or Federal program); or"],[1,"(B) intended for, and solely occupied by, persons 62 years of age or older; or"],[1,"(C) intended and operated for occupancy by persons 55 years of age or older, and—"],[2,"(i) at least 80 percent of the occupied units are occupied by at least one person who is 55 years of age or older;"],[2,"(ii) the housing facility or community publishes and adheres to policies and procedures that demonstrate the intent required under this subparagraph; and"],[2,"(iii) the housing facility or community complies with rules issued by the Secretary for verification of occupancy, which shall—"],[3,"(I) provide for verification by reliable surveys and affidavits; and"],[3,"(II) include examples of the types of policies and procedures relevant to a determination of compliance with the requirement of clause (ii). Such surveys and affidavits shall be admissible in administrative and judicial proceedings for the purposes of such verification."],[0,"(3) Housing shall not fail to meet the requirements for housing for older persons by reason of:"],[1,"(A) persons residing in such housing as of September 13, 1988, who do not meet the age requirements of subsections 1 (2)(B) or (C): Provided, That new occupants of such housing meet the age requirements of subsections 1 (2)(B) or (C); or"],[1,"(B) unoccupied units: Provided, That such units are reserved for occupancy by persons who meet the age requirements of subsections 1 (2)(B) or (C)."],[0,"(4) Nothing in this subchapter prohibits conduct against a person because such person has been convicted by any court of competent jurisdiction of the illegal manufacture or distribution of a controlled substance as defined in section 802 of title 21."],[0,"(5)(A) A person shall not be held personally liable for monetary damages for a violation of this subchapter if such person reasonably relied, in good faith, on the application of the exemption under this subsection relating to housing for older persons."],[0,"(B) For the purposes of this paragraph, a person may only show good faith reliance on the application of the exemption by showing that—"],[1,"(i) such person has no actual knowledge that the facility or community is not, or will not be, eligible for such exemption; and"],[1,"(ii) the facility or community has stated formally, in writing, that the facility or community complies with the requirements for such exemption."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3607?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3607. Religious organization or private club exemption","tname":"The Public Health and Welfare","by":{"0":"5, 25, 5, 25, 26"}},{"t":"usc","label":"42 U.S.C. § 3608","url":"https://www.law.cornell.edu/uscode/text/42/3608","subs":["(a)"],"by":{"0":"1, 13"}},{"t":"usc","label":"42 U.S.C. § 3610","url":"https://www.law.cornell.edu/uscode/text/42/3610","by":{"0":"15"}},{"t":"usc","label":"42 U.S.C. § 3612","url":"https://www.law.cornell.edu/uscode/text/42/3612","subs":["(g)","(h)","(o)"],"stext":{"head":"§3612. Enforcement by Secretary","paras":[[0,"(a) Election of judicial determination"],[0,"When a charge is filed under section 3610 of this title, a complainant, a respondent, or an aggrieved person on whose behalf the complaint was filed, may elect to have the claims asserted in that charge decided in a civil action under subsection (o) in lieu of a hearing under subsection (b). The election must be made not later than 20 days after the receipt by the electing person of service under section 3610(h) of this title or, in the case of the Secretary, not later than 20 days after such service. The person making such election shall give notice of doing so to the Secretary and to all other complainants and respondents to whom the charge relates."],[0,"(b) Administrative law judge hearing in absence of election"],[0,"If an election is not made under subsection (a) with respect to a charge filed under section 3610 of this title, the Secretary shall provide an opportunity for a hearing on the record with respect to a charge issued under section 3610 of this title. The Secretary shall delegate the conduct of a hearing under this section to an administrative law judge appointed under section 3105 of title 5. The administrative law judge shall conduct the hearing at a place in the vicinity in which the discriminatory housing practice is alleged to have occurred or to be about to occur."],[0,"(c) Rights of parties"],[0,"At a hearing under this section, each party may appear in person, be represented by counsel, present evidence, cross-examine witnesses, and obtain the issuance of subpoenas under section 3611 of this title. Any aggrieved person may intervene as a party in the proceeding. The Federal Rules of Evidence apply to the presentation of evidence in such hearing as they would in a civil action in a United States district court."],[0,"(d) Expedited discovery and hearing"],[0,"(1) Discovery in administrative proceedings under this section shall be conducted as expeditiously and inexpensively as possible, consistent with the need of all parties to obtain relevant evidence."],[0,"(2) A hearing under this section shall be conducted as expeditiously and inexpensively as possible, consistent with the needs and rights of the parties to obtain a fair hearing and a complete record."],[0,"(3) The Secretary shall, not later than 180 days after September 13, 1988, issue rules to implement this subsection."],[0,"(e) Resolution of charge"],[0,"Any resolution of a charge before a final order under this section shall require the consent of the aggrieved person on whose behalf the charge is issued."],[0,"(f) Effect of trial of civil action on administrative proceedings"],[0,"An administrative law judge may not continue administrative proceedings under this section regarding any alleged discriminatory housing practice after the beginning of the trial of a civil action commenced by the aggrieved party under an Act of Congress or a State law, seeking relief with respect to that discriminatory housing practice."],[0,"(g) Hearings, findings and conclusions, and order"],[0,"(1) The administrative law judge shall commence the hearing under this section no later than 120 days following the issuance of the charge, unless it is impracticable to do so. If the administrative law judge is unable to commence the hearing within 120 days after the issuance of the charge, the administrative law judge shall notify the Secretary, the aggrieved person on whose behalf the charge was filed, and the respondent, in writing of the reasons for not doing so."],[0,"(2) The administrative law judge shall make findings of fact and conclusions of law within 60 days after the end of the hearing under this section, unless it is impracticable to do so. If the administrative law judge is unable to make findings of fact and conclusions of law within such period, or any succeeding 60-day period thereafter, the administrative law judge shall notify the Secretary, the aggrieved person on whose behalf the charge was filed, and the respondent, in writing of the reasons for not doing so."],[0,"(3) If the administrative law judge finds that a respondent has engaged or is about to engage in a discriminatory housing practice, such administrative law judge shall promptly issue an order for such relief as may be appropriate, which may include actual damages suffered by the aggrieved person and injunctive or other equitable relief. Such order may, to vindicate the public interest, assess a civil penalty against the respondent—"],[1,"(A) in an amount not exceeding $10,000 if the respondent has not been adjudged to have committed any prior discriminatory housing practice;"],[1,"(B) in an amount not exceeding $25,000 if the respondent has been adjudged to have committed one other discriminatory housing practice during the 5-year period ending on the date of the filing of this charge; and"],[1,"(C) in an amount not exceeding $50,000 if the respondent has been adjudged to have committed 2 or more discriminatory housing practices during the 7-year period ending on the date of the filing of this charge;"],[0,"except that if the acts constituting the discriminatory housing practice that is the object of the charge are committed by the same natural person who has been previously adjudged to have committed acts constituting a discriminatory housing practice, then the civil penalties set forth in subparagraphs (B) and (C) may be imposed without regard to the period of time within which any subsequent discriminatory housing practice occurred."],[0,"(4) No such order shall affect any contract, sale, encumbrance, or lease consummated before the issuance of such order and involving a bona fide purchaser, encumbrancer, or tenant without actual notice of the charge filed under this subchapter."],[0,"(5) In the case of an order with respect to a discriminatory housing practice that occurred in the course of a business subject to a licensing or regulation by a governmental agency, the Secretary shall, not later than 30 days after the date of the issuance of such order (or, if such order is judicially reviewed, 30 days after such order is in substance affirmed upon such review)—"],[1,"(A) send copies of the findings of fact, conclusions of law, and the order, to that governmental agency; and"],[1,"(B) recommend to that governmental agency appropriate disciplinary action (including, where appropriate, the suspension or revocation of the license of the respondent)."],[0,"(6) In the case of an order against a respondent against whom another order was issued within the preceding 5 years under this section, the Secretary shall send a copy of each such order to the Attorney General."],[0,"(7) If the administrative law judge finds that the respondent has not engaged or is not about to engage in a discriminatory housing practice, as the case may be, such administrative law judge shall enter an order dismissing the charge. The Secretary shall make public disclosure of each such dismissal."],[0,"(h) Review by Secretary; service of final order"],[0,"(1) The Secretary may review any finding, conclusion, or order issued under subsection (g). Such review shall be completed not later than 30 days after the finding, conclusion, or order is so issued; otherwise the finding, conclusion, or order becomes final."],[0,"(2) The Secretary shall cause the findings of fact and conclusions of law made with respect to any final order for relief under this section, together with a copy of such order, to be served on each aggrieved person and each respondent in the proceeding."],[0,"(i) Judicial review"],[0,"(1) Any party aggrieved by a final order for relief under this section granting or denying in whole or in part the relief sought may obtain a review of such order under chapter 158 of title 28."],[0,"(2) Notwithstanding such chapter, venue of the proceeding shall be in the judicial circuit in which the discriminatory housing practice is alleged to have occurred, and filing of the petition for review shall be not later than 30 days after the order is entered."],[0,"(j) Court enforcement of administrative order upon petition by Secretary"],[0,"(1) The Secretary may petition any United States court of appeals for the circuit in which the discriminatory housing practice is alleged to have occurred or in which any respondent resides or transacts business for the enforcement of the order of the administrative law judge and for appropriate temporary relief or restraining order, by filing in such court a written petition praying that such order be enforced and for appropriate temporary relief or restraining order."],[0,"(2) The Secretary shall file in court with the petition the record in the proceeding. A copy of such petition shall be forthwith transmitted by the clerk of the court to the parties to the proceeding before the administrative law judge."],[0,"(k) Relief which may be granted"],[0,"(1) Upon the filing of a petition under subsection (i) or (j), the court may—"],[1,"(A) grant to the petitioner, or any other party, such temporary relief, restraining order, or other order as the court deems just and proper;"],[1,"(B) affirm, modify, or set aside, in whole or in part, the order, or remand the order for further proceedings; and"],[1,"(C) enforce such order to the extent that such order is affirmed or modified."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3612?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3612. Enforcement by Secretary","tname":"The Public Health and Welfare","by":{"0":"1, 15, 13, 15, 13, 15, 2"}},{"t":"usc","label":"42 U.S.C. § 3614","url":"https://www.law.cornell.edu/uscode/text/42/3614","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 3614a","url":"https://www.law.cornell.edu/uscode/text/42/3614a","by":{"0":"1, 13"}},{"t":"law","label":"Pub. L. No. 100-430","url":"https://www.govinfo.gov/link/statute/102/1619","by":{"0":"4"}},{"t":"usc","label":"26 U.S.C. § 42","url":"https://www.law.cornell.edu/uscode/text/26/42","subs":["(m)(1)(A)"],"stext":{"head":"§42. Low-income housing credit","paras":[[0,"(a) In general"],[0,"For purposes of section 38, the amount of the low-income housing credit determined under this section for any taxable year in the credit period shall be an amount equal to—"],[1,"(1) the applicable percentage of"],[1,"(2) the qualified basis of each qualified low-income building."],[0,"(b) Applicable percentage: 70 percent present value credit for certain new buildings; 30 percent present value credit for certain other buildings"],[0,"(1) Determination of applicable percentage"],[1,"For purposes of this section—"],[0,"(A) In general"],[2,"The term \"applicable percentage\" means, with respect to any building, the appropriate percentage prescribed by the Secretary for the earlier of—"],[3,"(i) the month in which such building is placed in service, or"],[3,"(ii) at the election of the taxpayer—"],[4,"(I) the month in which the taxpayer and the housing credit agency enter into an agreement with respect to such building (which is binding on such agency, the taxpayer, and all successors in interest) as to the housing credit dollar amount to be allocated to such building, or"],[4,"(II) in the case of any building to which subsection (h)(4)(B) applies, the month in which the tax-exempt obligations are issued."],[0,"A month may be elected under clause (ii) only if the election is made not later than the 5th day after the close of such month. Such an election, once made, shall be irrevocable."],[0,"(B) Method of prescribing percentages"],[2,"The percentages prescribed by the Secretary for any month shall be percentages which will yield over a 10-year period amounts of credit under subsection (a) which have a present value equal to—"],[3,"(i) 70 percent of the qualified basis of a new building which is not federally subsidized for the taxable year, and"],[3,"(ii) 30 percent of the qualified basis of a building not described in clause (i)."],[0,"(C) Method of discounting"],[2,"The present value under subparagraph (B) shall be determined—"],[3,"(i) as of the last day of the 1st year of the 10-year period referred to in subparagraph (B),"],[3,"(ii) by using a discount rate equal to 72 percent of the average of the annual Federal mid-term rate and the annual Federal long-term rate applicable under section 1274(d)(1) to the month applicable under clause (i) or (ii) of subparagraph (A) and compounded annually, and"],[3,"(iii) by assuming that the credit allowable under this section for any year is received on the last day of such year."],[0,"(2) Minimum credit rate for non-federally subsidized new buildings"],[1,"In the case of any new building—"],[2,"(A) which is placed in service by the taxpayer after the date of the enactment of this paragraph, and"],[2,"(B) which is not federally subsidized for the taxable year,"],[1,"the applicable percentage shall not be less than 9 percent."],[0,"(3) Minimum credit rate"],[1,"In the case of any new or existing building to which paragraph (2) does not apply and which is placed in service by the taxpayer after December 31, 2020, the applicable percentage shall not be less than 4 percent."],[0,"(4) Cross references"],[2,"(A) For treatment of certain rehabilitation expenditures as separate new buildings, see subsection (e)."],[2,"(B) For determination of applicable percentage for increases in qualified basis after the 1st year of the credit period, see subsection (f)(3)."],[2,"(C) For authority of housing credit agency to limit applicable percentage and qualified basis which may be taken into account under this section with respect to any building, see subsection (h)(7)."],[0,"(c) Qualified basis; qualified low-income building"],[0,"For purposes of this section—"],[0,"(1) Qualified basis"],[0,"(A) Determination"],[2,"The qualified basis of any qualified low-income building for any taxable year is an amount equal to—"],[3,"(i) the applicable fraction (determined as of the close of such taxable year) of"],[3,"(ii) the eligible basis of such building (determined under subsection (d)(5))."],[0,"(B) Applicable fraction"],[2,"For purposes of subparagraph (A), the term \"applicable fraction\" means the smaller of the unit fraction or the floor space fraction."],[0,"(C) Unit fraction"],[2,"For purposes of subparagraph (B), the term \"unit fraction\" means the fraction—"],[3,"(i) the numerator of which is the number of low-income units in the building, and"],[3,"(ii) the denominator of which is the number of residential rental units (whether or not occupied) in such building."],[0,"(D) Floor space fraction"],[2,"For purposes of subparagraph (B), the term \"floor space fraction\" means the fraction—"],[3,"(i) the numerator of which is the total floor space of the low-income units in such building, and"],[3,"(ii) the denominator of which is the total floor space of the residential rental units (whether or not occupied) in such building."],[0,"(E) Qualified basis to include portion of building used to provide supportive services for homeless"],[2,"In the case of a qualified low-income building described in subsection (i)(3)(B)(iii), the qualified basis of such building for any taxable year shall be increased by the lesser of—"],[3,"(i) so much of the eligible basis of such building as is used throughout the year to provide supportive services designed to assist tenants in locating and retaining permanent housing, or"],[3,"(ii) 20 percent of the qualified basis of such building (determined without regard to this subparagraph)."],[0,"(2) Qualified low-income building"],[1,"The term \"qualified low-income building\" means any building—"],[2,"(A) which is part of a qualified low-income housing project at all times during the period—"],[3,"(i) beginning on the 1st day in the compliance period on which such building is part of such a project, and"],[3,"(ii) ending on the last day of the compliance period with respect to such building, and"],[2,"(B) to which the amendments made by section 201(a) of the Tax Reform Act of 1986 apply."],[0,"(d) Eligible basis"],[0,"For purposes of this section—"],[0,"(1) New buildings"],[1,"The eligible basis of a new building is its adjusted basis as of the close of the 1st taxable year of the credit period."],[0,"(2) Existing buildings"],[0,"(A) In general"],[2,"The eligible basis of an existing building is—"],[3,"(i) in the case of a building which meets the requirements of subparagraph (B), its adjusted basis as of the close of the 1st taxable year of the credit period, and"],[3,"(ii) zero in any other case."],[0,"(B) Requirements"],[2,"A building meets the requirements of this subparagraph if—"],[3,"(i) the building is acquired by purchase (as defined in section 179(d)(2)),"],[3,"(ii) there is a period of at least 10 years between the date of its acquisition by the taxpayer and the date the building was last placed in service,"],[3,"(iii) the building was not previously placed in service by the taxpayer or by any person who was a related person with respect to the taxpayer as of the time previously placed in service, and"],[3,"(iv) except as provided in subsection (f)(5), a credit is allowable under subsection (a) by reason of subsection (e) with respect to the building."],[0,"(C) Adjusted basis"],[2,"For purposes of subparagraph (A), the adjusted basis of any building shall not include so much of the basis of such building as is determined by reference to the basis of other property held at any time by the person acquiring the building."],[0,"(D) Special rules for subparagraph (B)"],[0,"(i) Special rules for certain transfers"],[3,"For purposes of determining under subparagraph (B)(ii) when a building was last placed in service, there shall not be taken into account any placement in service—"],[4,"(I) in connection with the acquisition of the building in a transaction in which the basis of the building in the hands of the person acquiring it is determined in whole or in part by reference to the adjusted basis of such building in the hands of the person from whom acquired,"],[4,"(II) by a person whose basis in such building is determined under section 1014(a) (relating to property acquired from a decedent),"],[4,"(III) by any governmental unit or qualified nonprofit organization (as defined in subsection (h)(5)) if the requirements of subparagraph (B)(ii) are met with respect to the placement in service by such unit or organization and all the income from such property is exempt from Federal income taxation,"],[4,"(IV) by any person who acquired such building by foreclosure (or by instrument in lieu of foreclosure) of any purchase-money security interest held by such person if the requirements of subparagraph (B)(ii) are met with respect to the placement in service by such person and such building is resold within 12 months after the date such building is placed in service by such person after such foreclosure, or"],[4,"(V) of a single-family residence by any individual who owned and used such residence for no other purpose than as his principal residence."],[0,"(ii) Related person"],[3,"For purposes of subparagraph (B)(iii), a person (hereinafter in this subclause referred to as the \"related person\") is related to any person if the related person bears a relationship to such person specified in section 267(b) or 707(b)(1), or the related person and such person are engaged in trades or businesses under common control (within the meaning of subsections (a) and (b) of section 52)."],[0,"(3) Eligible basis reduced where disproportionate standards for units"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), the eligible basis of any building shall be reduced by an amount equal to the portion of the adjusted basis of the building which is attributable to residential rental units in the building which are not low-income units and which are above the average quality standard of the low-income units in the building."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/42?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§42. Low-income housing credit","tname":"Internal Revenue Code","by":{"0":"7, 7"}},{"t":"usc","label":"42 U.S.C. § 3535","url":"https://www.law.cornell.edu/uscode/text/42/3535","subs":["(d)"],"by":{"0":"13"}}]};